-- Source: USGS Water Data APIs (6694816 rows)
-- Generated by gen_mart_models.py
-- Fixed 2026-09-20: bare try_to_number()/try_to_double()/try_to_date() casts replaced in place with the project's guarded macros (stg_int/stg_float/stg_date, macros/staging_casts.sql) -- a value that doesn't parse cleanly now reads NULL instead of being silently rounded or misparsed. Kept on source() (not ref()) because this mart carries its own documented timestamp-precision fix and dedup (qualify) that must stay intact.

-- TIMESTAMP FIX (2026-08-25 verification): the previous cast used ripple_dt(), a
-- DATE-only guarded cast, on a column that is actually a fine-grained clock --
-- 'real-time' rows are 15-minute readings ('2026-06-25T00:15:00.000-05:00', 96/
-- day/site/parameter), 'daily' rows are once-a-day. Truncating to a bare date
-- collapsed up to ~96 real readings/day onto one row: distinct (site_no,
-- parameter_cd, datetime, data_type) combos crashed from 6,694,816 rows to
-- 100,323 -- almost total data loss, and the actual cause of this test's failure.
-- Fixed by parsing the full ISO-8601 timestamp (every one of 6,694,816 values
-- parses; each already carries its own UTC offset) and converting to naive UTC
-- per the Ripple time standard (macros/ripple_time.sql rule 5) instead of
-- truncating the time of day away.

-- DEDUP (2026-08-25 verification): even with full timestamp precision preserved,
-- landing still carries 181,647 (site_no, parameter_cd, datetime, data_type) keys
-- shared by more than one row (237,864 excess rows, ~3.6% of the table), all
-- within a single load run (one _SOURCE_RUN_ID). About 30K of those are exact
-- duplicate rows (harmless re-publishes). The rest carry genuinely DIFFERENT
-- VALUE readings at the same site+parameter+instant -- e.g. site 01435000,
-- parameter 00010 (water temperature) logs 21 different readings for one
-- 15-minute timestamp, all with matching site metadata. USGS's live-data service
-- can carry more than one underlying time series (different sensor/method) per
-- site+parameter, and this landing table never captured a series/method id to
-- tell them apart -- that dimension was lost upstream of dbt (loader/API
-- flattening) and cannot be reconstructed from what's stored. A deterministic
-- pick (by value, then content hash) keeps exactly one real, non-fabricated
-- reading per key so the declared grain holds. This is a known, documented
-- data-loss point, not a claim that the kept reading is "the" authoritative one.

with source as (
    select * from {{ source('ripple_raw', 'FED_USGS_WATER') }}
    qualify row_number() over (
        partition by SITE_NO, PARAMETER_CD, DATETIME, DATA_TYPE
        order by "VALUE", _SRC_SHA256,
             -- tie-breakers 2026-09-18: the row's own values, so the same row wins every run
             SITE_NAME nulls last, PARAMETER_NAME nulls last, UNIT_CD nulls last, QUALIFIER nulls last,
             STATE_CD nulls last, COUNTY_CD nulls last, HUC_CD nulls last, LATITUDE nulls last,
             LONGITUDE nulls last, AGENCY_CD nulls last
) = 1
)

select
    SITE_NO as site_no,
    SITE_NAME as site_name,
    PARAMETER_CD as parameter_cd,
    PARAMETER_NAME as parameter_name,
    convert_timezone('UTC', {{ stg_ts_tz('DATETIME') }})::timestamp_ntz as datetime,
    {{ stg_float('"VALUE"') }} as value,
    UNIT_CD as unit_cd,
    QUALIFIER as qualifier,
    STATE_CD as state_cd,
    COUNTY_CD as county_cd,
    HUC_CD as huc_cd,
    {{ stg_float('"LATITUDE"') }} as latitude,
    {{ stg_float('"LONGITUDE"') }} as longitude,
    AGENCY_CD as agency_cd,
    DATA_TYPE as data_type
from source
